import gzip,csv
rows=[]
with gzip.open('studies/data/raw/paper_2_GSE21618_series_matrix.txt.gz','rt') as f:
 for r in csv.reader(f,delimiter='\t'):
  if not r:continue
  if r[0]=='!series_matrix_table_begin':break
  if r[0].startswith('!Sample_'):rows.append(r)
for i,t in enumerate(next(r for r in rows if r[0]=='!Sample_title')[1:],1):
 if '0h' in t or 'Control' in t:
  print(t,' | '.join(r[i] for r in rows if r[0] in ['!Sample_source_name_ch1','!Sample_description']))
